INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shingle-stair', 'east', 'the-track-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-storm-line', 'east', 'the-boulder-beach', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-track-head', 'door', 'The Track Head', 'The made road ends. Not at a wall or a gate or anything that decided it — the last of the laid stone simply stops being laid, and what continues east is a worn place in the turf of exactly the same width. Somebody''s responsibility finished here and nobody''s began. From this step on, everything under your boots got that way by being walked on.', 0, 0, 'mountain', 0, 69, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-track-head', 'east', 'the-first-rise', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-track-head', 'west', 'the-shingle-stair', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-boulder-beach', 'door', 'The Boulder Beach', 'The shingle coarsens westward into stones you could not lift, then into stones the size of carts, and the tideline goes over and around them without ever getting up onto the land properly. These did not come from the sea. They came down, a long time ago, and the water has been failing to move them ever since.', 0, 0, 'mountain', 0, 68, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-beach', 'east', 'the-burn-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-beach', 'west', 'the-storm-line', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-burn-mouth', 'door', 'The Burn Mouth', 'Water comes out of the hill here and goes into the sea across forty feet of gravel, in a dozen shallow braids that shift with every spate. It is loud out of all proportion to its size. Follow it up and it will take you as far as it comes from, which is further than it looks.', 0, 0, 'mountain', 0, 69, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-burn-mouth', 'south', 'the-cobble-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-burn-mouth', 'east', 'the-thorn-scrub', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-burn-mouth', 'west', 'the-boulder-beach', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cobble-bank', 'door', 'The Cobble Bank', 'A long low bank of rounded stone thrown up where the burn meets the tide, every cobble grey and identical and perfectly smooth. Standing on it you sink and slide with each step and the whole bank talks under you. Nothing grows on it. Nothing has time to.', 0, 0, 'mountain', 0, 69, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cobble-bank', 'north', 'the-burn-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cobble-bank', 'east', 'the-lower-beck', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-first-rise', 'door', 'The First Rise', 'The ground tilts. It is not steep and it does not look like anything, but your breathing changes within a dozen strides and does not change back. Behind you the water is already lower than you are. Ahead the slope goes up and up in the same unremarkable way for longer than you can see.', 0, 0, 'mountain', 0, 70, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-rise', 'north', 'the-wind-flat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-rise', 'south', 'the-thorn-scrub', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-rise', 'east', 'the-rush-hollow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-rise', 'west', 'the-track-head', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wind-flat', 'door', 'The Wind Flat', 'A shelf of level ground with nothing on it but wind-cropped grass an inch high, lying so flat and cut so even it looks mown. Nothing has mown it. The wind comes off the water and over this shelf without meeting anything at all, and it has been doing that long enough to decide what grows and how tall.', 0, 0, 'mountain', 0, 70, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-flat', 'south', 'the-first-rise', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-flat', 'east', 'the-turf-wall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-thorn-scrub', 'door', 'The Thorn Scrub', 'Blackthorn grown into a low dense mat, waist high and impassable except where the animals have driven tunnels through it. The tunnels are the right height for something on four legs and the wrong height for you. Everything in here has spines and everything leans the same way, away from the sea.', 0, 0, 'mountain', 0, 70, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thorn-scrub', 'north', 'the-first-rise', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thorn-scrub', 'south', 'the-lower-beck', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thorn-scrub', 'west', 'the-burn-mouth', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lower-beck', 'door', 'The Lower Beck', 'The burn runs in a shallow trough of its own making, between banks of turf it has undercut and dropped in. The water is peat-brown in the deep parts and clear over the gravel and cold enough to ache your hands within a count of ten. There is no path along it. There is just the side of it, which is where you walk.', 0, 0, 'mountain', 0, 70, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-beck', 'north', 'the-thorn-scrub', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-beck', 'south', 'the-alder-thicket', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-beck', 'east', 'the-clapper', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-beck', 'west', 'the-cobble-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-alder-thicket', 'door', 'The Alder Thicket', 'Alders standing in the wet, close together and none of them tall, with their roots out of the ground in grey knuckled tangles where the burn has taken the soil from under them. It is dark in here at midday. Everything is either water or root and there is no ground between the two you can trust.', 0, 0, 'mountain', 0, 70, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-alder-thicket', 'north', 'the-lower-beck', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-alder-thicket', 'east', 'the-beck-narrows', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-turf-wall', 'door', 'The Turf Wall', 'A wall built of turf sods laid like bricks, chest high once and thigh high now, running away north and south along the contour until it fades into the slope. It is not keeping anything in or out. It marks where the grazing was worth walling, and the fact that it stops means somebody decided, precisely, where that was.', 0, 0, 'mountain', 0, 71, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turf-wall', 'north', 'the-shieling', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turf-wall', 'south', 'the-rush-hollow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turf-wall', 'east', 'the-last-pasture', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turf-wall', 'west', 'the-wind-flat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shieling', 'door', 'The Shieling', 'A single hut of stone and turf built into the slope with its back to the weather, low enough that you duck, and dry inside, which is more than the mountain offers anywhere else. People came up here with the animals for the summer months and went down again before the weather turned, every year, for a very long time, and then one year did not come. Somebody is here now. He does not say who or why, and the fire is lit.', 1, 0, 'mountain', 1, 71, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shieling', 'north', 'the-nettle-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shieling', 'south', 'the-turf-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shieling', 'east', 'the-milking-fold', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-milking-fold', 'door', 'The Milking Fold', 'A small round pen of dry stone, waist high, with a gap in it and a flat worn slab beside the gap where somebody sat. Beasts were brought in here twice a day and let out again and the ground inside is still a different colour from the ground outside. It will be a different colour for another hundred years.', 0, 0, 'mountain', 0, 72, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-milking-fold', 'north', 'the-hearth-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-milking-fold', 'south', 'the-last-pasture', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-milking-fold', 'west', 'the-shieling', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-nettle-ground', 'door', 'The Nettle Ground', 'Nettles, shoulder high, in a dense stand about the size of a house and nowhere else on this hillside. Nettles grow where people lived — on old middens, on the ground by a door, wherever the dung went. The people are two hundred years gone and the nettles have not noticed and will not.', 0, 0, 'mountain', 0, 71, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-nettle-ground', 'south', 'the-shieling', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-nettle-ground', 'east', 'the-hearth-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hearth-stone', 'door', 'The Hearth Stone', 'A hearth without a house: one broad flat stone with a ring of smaller ones round it, reddened right through by more fires than anybody could count, sitting in open grass with no wall or post or footing anywhere near it. Whatever stood over it went back into the ground. The stone will not. You could light a fire on it tonight and it would work.', 0, 1, 'mountain', 0, 72, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hearth-stone', 'north', 'the-goat-track', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hearth-stone', 'south', 'the-milking-fold', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hearth-stone', 'west', 'the-nettle-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-last-pasture', 'door', 'The Last Pasture', 'Grass — real grass, green and thick and worth something — in a long sloping field with the wall below it and the hill above. This is the top of the good ground and everybody who ever came up here knew it. Above this the grass gets thinner every fifty feet and stops being a crop and starts being whatever will hold on.', 0, 0, 'mountain', 0, 72, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-pasture', 'north', 'the-milking-fold', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-pasture', 'south', 'the-stell', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-pasture', 'east', 'the-bracken-slope', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-pasture', 'west', 'the-turf-wall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-rush-hollow', 'door', 'The Rush Hollow', 'A dip holding water it cannot drain, gone entirely to soft rush in dark clumps you step between rather than through. Underfoot it is black and gives. Something has been lying up here: there is a pressed oval in the rushes, big enough to matter, and the stems in it have not sprung back yet.', 0, 0, 'mountain', 0, 71, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rush-hollow', 'north', 'the-turf-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rush-hollow', 'east', 'the-stell', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rush-hollow', 'west', 'the-first-rise', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-stell', 'door', 'The Stell', 'A circular dry-stone shelter built in a ring so that beasts inside it could always get out of the wind whichever way it blew — a piece of very good thinking done by somebody with nothing but stone and a lot of time. Half of it has been roofed over since, badly, with poles and turf and a stretched hide, and there is a fire under the roofed half and a man keeping it. He came up with the last of the summer people and did not go down with them.', 1, 0, 'mountain', 1, 72, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stell', 'north', 'the-last-pasture', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stell', 'east', 'the-boulder-field', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stell', 'west', 'the-rush-hollow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bracken-slope', 'door', 'The Bracken Slope', 'Bracken to the chest, unbroken across the whole face of the slope, hiding the ground and every hole and stone in it completely. It comes in where grazing stops and it does not go out again. Walking through it you cannot see your own feet, and you can hear things moving that you will not see at all.', 0, 0, 'mountain', 0, 73, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bracken-slope', 'north', 'the-cotton-grass', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bracken-slope', 'south', 'the-boulder-field', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bracken-slope', 'west', 'the-last-pasture', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cotton-grass', 'door', 'The Cotton Grass', 'Bog cotton, thousands of it, each on its own thin stalk, all leaning together and letting go together when the wind comes over. From below it reads as a white haze lying on the hill. Up close it is a signal you should read: it grows where the ground will not hold you.', 0, 0, 'mountain', 0, 73, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cotton-grass', 'north', 'the-peat-hags', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cotton-grass', 'south', 'the-bracken-slope', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cotton-grass', 'east', 'the-drowned-fence', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-peat-hags', 'door', 'The Peat Hags', 'The peat has torn open into a maze of steep black-sided channels, six feet deep, with flat-topped islands of heather standing between them. You go down into one and along it and up out of it, or you go round, and either way you cannot see over the tops while you are in there. Old wood sticks out of the cut faces — whole trunks, black and sound, from a forest that stood here before any of this was peat.', 0, 0, 'mountain', 0, 73, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-peat-hags', 'north', 'the-hanging-turf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-peat-hags', 'south', 'the-cotton-grass', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-peat-hags', 'east', 'the-peat-pool', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-peat-pool', 'door', 'The Peat Pool', 'A pool in the peat, small and perfectly still and the colour of strong tea held to a candle, with no inlet and no outlet and no bottom you can see. Nothing lives in it — the water is too sour. Things that go into water like this do not rot. They keep.', 0, 0, 'mountain', 0, 74, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-peat-pool', 'south', 'the-drowned-fence', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-peat-pool', 'west', 'the-peat-hags', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-drowned-fence', 'door', 'The Drowned Fence', 'A line of fence posts walking away up the slope and into the bog, each one shorter than the last as the ground swallows them, until the last two show as knuckles of grey wood in the moss and then there are no more. Whoever set these was fencing ground that has since eaten the fence. There is wire still strung between the first four.', 0, 0, 'mountain', 0, 74, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drowned-fence', 'north', 'the-peat-pool', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drowned-fence', 'west', 'the-cotton-grass', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-clapper', 'door', 'The Clapper', 'Three slabs of stone laid end to end across the burn on two piers of stacked rock — the simplest bridge there is, and the oldest kind, and it has not moved. Nobody signs a thing like this. Somebody needed to get across with something heavy, once, and solved it, and the solution is still solving it.', 0, 0, 'mountain', 0, 71, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-clapper', 'south', 'the-beck-narrows', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-clapper', 'east', 'the-water-slide', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-clapper', 'west', 'the-lower-beck', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-beck-narrows', 'door', 'The Beck Narrows', 'The burn goes into a slot barely wider than your shoulders, walled in rock on both sides and roofed in places by boulders that fell in and jammed. The noise in here doubles. You can bridge the whole burn with one stride and you can also not see the sky.', 0, 0, 'mountain', 0, 71, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-narrows', 'north', 'the-clapper', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-narrows', 'east', 'the-plunge-pool', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-narrows', 'west', 'the-alder-thicket', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-plunge-pool', 'door', 'The Plunge Pool', 'A round green pool scoured out under a fall of about the height of two men, deep enough in the middle that the bottom goes from gravel to nothing. The spray keeps a ring of ground round it permanently wet, and the moss on that ring is the brightest thing in this whole valley.', 0, 0, 'mountain', 0, 72, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plunge-pool', 'north', 'the-water-slide', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plunge-pool', 'south', 'the-sphagnum-flat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plunge-pool', 'east', 'the-fallen-birch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plunge-pool', 'west', 'the-beck-narrows', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-water-slide', 'door', 'The Water Slide', 'A long smooth tongue of bare rock the burn runs down in a sheet an inch deep, polished over centuries into something you could genuinely slide on, and will if you put a foot wrong. There is nothing to hold. The rock is not sharp anywhere and that is precisely the problem.', 0, 0, 'mountain', 0, 72, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-water-slide', 'south', 'the-plunge-pool', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-water-slide', 'east', 'the-gravel-race', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-water-slide', 'west', 'the-clapper', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-gravel-race', 'door', 'The Gravel Race', 'The burn spreads and shallows over a bed of loose gravel that shifts audibly as the water works it, a low grinding under the water noise. Every stone here is on its way down. Stand in it long enough and you can feel the bed moving under your boots.', 0, 0, 'mountain', 0, 73, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gravel-race', 'south', 'the-fallen-birch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gravel-race', 'east', 'the-beck-fork', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gravel-race', 'west', 'the-water-slide', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fallen-birch', 'door', 'The Fallen Birch', 'A birch came down across the water some years ago and has stayed, wedged, with the burn running under it and a raft of everything the burn has carried since piled against its upstream side. The trunk is slick and green. It is the only easy crossing for a long way and it is not easy.', 0, 0, 'mountain', 0, 73, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-birch', 'north', 'the-gravel-race', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-birch', 'east', 'the-dry-course', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-birch', 'west', 'the-plunge-pool', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-beck-fork', 'door', 'The Beck Fork', 'Two waters meet, and you can see that they are not the same water: one comes down clear and quick off the rock, the other comes brown and slow out of the peat, and for thirty feet below the junction they run side by side in the same channel without mixing. Then they mix.', 0, 0, 'mountain', 0, 74, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-fork', 'north', 'the-hollow-under', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-fork', 'south', 'the-dry-course', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-fork', 'east', 'the-spring-eye', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-fork', 'west', 'the-gravel-race', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dry-course', 'door', 'The Dry Course', 'A stream bed with no stream in it: clean scoured rock, banks cut square, gravel graded and sorted exactly as running water sorts it, and not a drop anywhere. It runs when the hill is full and it is not full now. Everything about this place says water and there is none, and that should tell you what it is like when there is.', 0, 0, 'mountain', 0, 74, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-course', 'north', 'the-beck-fork', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-course', 'east', 'the-flood-gravel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-course', 'west', 'the-fallen-birch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-spring-eye', 'door', 'The Spring Eye', 'Water comes straight up out of flat ground here through a bed of pale sand, and the sand boils and settles and boils again where it rises, and the whole thing is about the size of a shield. It is doing this constantly and has been for longer than anything else in view has existed. It is the coldest water on this hill.', 0, 0, 'mountain', 0, 75, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-eye', 'south', 'the-flood-gravel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-eye', 'east', 'the-lower-force', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-eye', 'west', 'the-beck-fork', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-flood-gravel', 'door', 'The Flood Gravel', 'An apron of raw gravel and torn turf spread thirty yards wide across ground the burn does not normally reach, with boulders sitting on the surface where the water dropped them and stopped. This happened in one afternoon, some year, and the mountain has not tidied it and will not.', 0, 0, 'mountain', 0, 75, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-flood-gravel', 'north', 'the-spring-eye', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-flood-gravel', 'east', 'the-force-pool', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-flood-gravel', 'west', 'the-dry-course', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lower-force', 'door', 'The Lower Force', 'The burn comes over a lip of hard rock in one drop, twice your height, into the pool below, and the fall is narrow and heavy and hits like something solid. Standing beside it you cannot make yourself heard. There is a way up beside it if you use your hands.', 0, 0, 'mountain', 0, 76, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-force', 'south', 'the-force-pool', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-force', 'west', 'the-spring-eye', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-force-pool', 'door', 'The Force Pool', 'The catch-basin under the fall, black and turning slowly and colder than the air, walled on three sides by wet rock that never sees the sun. Things that come down the burn end up circling in here for a while before they go on. Some of them do not go on.', 0, 0, 'mountain', 0, 76, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-force-pool', 'north', 'the-lower-force', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-force-pool', 'south', 'the-black-runnel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-force-pool', 'west', 'the-flood-gravel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-boulder-field', 'door', 'The Boulder Field', 'Rock, from head-sized to house-sized, dumped across the whole width of the valley in no order whatever and left. There is no path through and no path round; you go over it, boulder to boulder, and the gaps between them go down further than you want to look. Every one of these came from somewhere higher up.', 0, 0, 'mountain', 0, 73, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-field', 'north', 'the-bracken-slope', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-field', 'east', 'the-erratic', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-field', 'west', 'the-stell', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-erratic', 'door', 'The Erratic', 'One boulder standing by itself on open ground, the size of a small house, of a stone that matches nothing anywhere near it. It was carried here and set down. The thing that carried it was ice, and the ice is gone, and this is what it left behind to say so.', 0, 0, 'mountain', 0, 74, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-erratic', 'south', 'the-hollow-under', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-erratic', 'east', 'the-moraine-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-erratic', 'west', 'the-boulder-field', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hollow-under', 'door', 'The Hollow Under', 'The erratic sits on three points and the fourth corner is off the ground, and under it there is a dry floor of sand the size of a small room, out of the wind and out of the rain and out of the sight of everything. Somebody is in here. There is a ring of stones for a fire, and the sand is swept, and she has been doing both long enough that the swept edge has a lip on it.', 1, 0, 'mountain', 1, 74, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow-under', 'north', 'the-erratic', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow-under', 'south', 'the-beck-fork', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow-under', 'east', 'the-stone-river', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-moraine-bank', 'door', 'The Moraine Bank', 'A long even ridge of mixed rubble running across the slope, out of place in a landscape of curves — too straight, too regular, sides at the same angle the whole length of it. It is the exact shape of the front of something that stopped here for a long time and then went back up.', 0, 0, 'mountain', 0, 75, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moraine-bank', 'north', 'the-scree-toe', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moraine-bank', 'south', 'the-stone-river', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moraine-bank', 'east', 'the-sorted-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moraine-bank', 'west', 'the-erratic', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-stone-river', 'door', 'The Stone River', 'A band of loose rock a hundred feet wide winding down the slope between banks of turf, for all the world like a watercourse with the water taken out. It moves. Not while you are watching, but the turf at its edges is torn and freshly buried and the whole thing is a foot further down the hill each year.', 0, 0, 'mountain', 0, 75, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-river', 'north', 'the-moraine-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-river', 'east', 'the-lichen-boulders', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-river', 'west', 'the-hollow-under', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sorted-ground', 'door', 'The Sorted Ground', 'The stones here have arranged themselves into rings and stripes — coarse rock in the lines, fine gravel between — over an area the size of a field, as neatly as if someone had raked it. Nobody raked it. Frost did it, lifting and dropping and lifting again, ten thousand winters of doing the same small thing.', 0, 0, 'mountain', 0, 76, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sorted-ground', 'south', 'the-lichen-boulders', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sorted-ground', 'east', 'the-cold-hollow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sorted-ground', 'west', 'the-moraine-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lichen-boulders', 'door', 'The Lichen Boulders', 'Every stone here carries a crust of lichen in grey-green plates and rings, and the biggest rings are the size of a spread hand. They grow about the width of a hair in a year. Doing the arithmetic on the one by your knee is not a comfortable way to spend a minute.', 0, 0, 'mountain', 0, 76, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lichen-boulders', 'north', 'the-sorted-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lichen-boulders', 'east', 'the-glacier-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lichen-boulders', 'west', 'the-stone-river', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-glacier-mouth', 'door', 'The Glacier Mouth', 'A dark arched hole at the foot of the rock where the burn comes out from under the mountain, wide enough to walk into and low enough that you would not for long. The air coming out is colder than the day. This is where the water starts being water, and the way in goes back further than the light does.', 0, 0, 'mountain', 0, 77, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glacier-mouth', 'north', 'the-cold-hollow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glacier-mouth', 'west', 'the-lichen-boulders', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cold-hollow', 'door', 'The Cold Hollow', 'A basin in the rock that the sun does not reach at any hour, holding a floor of grey rubble and a skin of old snow that has been there since some winter nobody remembers. It is markedly colder standing here than ten steps away, and you feel it as soon as you cross the line.', 0, 0, 'mountain', 0, 77, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-hollow', 'south', 'the-glacier-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-hollow', 'east', 'the-crag-shadow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-hollow', 'west', 'the-sorted-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-scree-toe', 'door', 'The Scree Toe', 'The bottom of a scree, where the falling stone has run out of slope and spread into a flat tongue over the turf. Down here the pieces are the biggest — they roll furthest — and they are locked together and stable and quiet. Everything above this line is not.', 0, 0, 'mountain', 0, 75, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scree-toe', 'south', 'the-moraine-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scree-toe', 'east', 'the-loose-slope', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-loose-slope', 'door', 'The Loose Slope', 'Scree at the angle it wants to be at, which is exactly as steep as loose rock can stand before it stops standing. Every step you take sends a small run of it away downhill, and every small run takes a little longer than the last to stop. You do not so much climb this as negotiate with it.', 0, 0, 'mountain', 0, 76, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-loose-slope', 'north', 'the-fan', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-loose-slope', 'east', 'the-shifting-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-loose-slope', 'west', 'the-scree-toe', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fan', 'door', 'The Fan', 'A perfect spreading cone of stone poured out of a gully above and laid down over the slope in a fan, sorted fine at the edges and coarse up the middle. It is beautiful from a distance and it is the single most tiring ground on this hill to cross.', 0, 0, 'mountain', 0, 76, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fan', 'north', 'the-shattered-rib', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fan', 'south', 'the-loose-slope', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fan', 'east', 'the-rock-glacier', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shifting-ground', 'door', 'The Shifting Ground', 'Big blocks resting on smaller ones, so that a slab the size of a door will tilt under your weight and settle back when you are off it. There is no way to tell which ones will do it. The noise a hillside makes when you cross it like this carries a very long way in this air.', 0, 0, 'mountain', 0, 77, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shifting-ground', 'north', 'the-rock-glacier', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shifting-ground', 'east', 'the-boulder-choke', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shifting-ground', 'west', 'the-loose-slope', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-rock-glacier', 'door', 'The Rock Glacier', 'A tongue of rubble with ridges across it like ripples, bulging out from the foot of the crag, and it is not a heap — it is flowing, with ice inside it doing the flowing, slower than anything you could measure in a life. It is going downhill. It will get there.', 0, 0, 'mountain', 0, 77, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rock-glacier', 'south', 'the-shifting-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rock-glacier', 'east', 'the-first-crag', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rock-glacier', 'west', 'the-fan', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-boulder-choke', 'door', 'The Boulder Choke', 'The gully above has jammed solid with fallen blocks, wedged one against another and holding each other up over gaps you could fall the length of your body into. There is a way through it at the back on hands and knees. Everything here is holding everything else here.', 0, 0, 'mountain', 0, 78, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-choke', 'north', 'the-first-crag', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-choke', 'south', 'the-crag-shadow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-choke', 'east', 'the-notch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-choke', 'west', 'the-shifting-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-first-crag', 'door', 'The First Crag', 'The first honest rock: a wall of it, wet, black, and going up out of sight past where the mist takes it. Up to now the mountain has been ground you could walk over given enough patience. This is the end of that argument.', 0, 0, 'mountain', 0, 78, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-crag', 'south', 'the-boulder-choke', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-crag', 'west', 'the-rock-glacier', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-crag-shadow', 'door', 'The Crag Shadow', 'The strip of ground along the base of the wall, in permanent shade, floored with everything the crag has dropped — flakes, blocks, a few things that were once whole. Nothing grows on it. There is a sound, every so often, of one more piece arriving somewhere along the line.', 0, 0, 'mountain', 0, 78, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crag-shadow', 'north', 'the-boulder-choke', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crag-shadow', 'south', 'the-gully-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crag-shadow', 'west', 'the-cold-hollow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-notch', 'door', 'The Notch', 'A slot in the crag line, no wider than a cart, with the ground rising through it and out the other side. It is the only break in the wall for as far as you can see in either direction, and everything that goes up this side of the mountain goes through here. There are tracks in the wet grit, and none of them are boots.', 0, 0, 'mountain', 0, 79, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-notch', 'west', 'the-boulder-choke', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shattered-rib', 'door', 'The Shattered Rib', 'A rib of harder rock standing proud of the slope and split from top to bottom by frost into slabs that lean apart like a book fanned open. You can walk into the gaps a little way. They are the width of a body and they do not go anywhere.', 0, 0, 'mountain', 0, 76, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shattered-rib', 'north', 'the-raven-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shattered-rib', 'south', 'the-fan', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-gully-foot', 'door', 'The Gully Foot', 'Where a gully in the crag comes down and delivers, onto a heap of its own leavings — grit, splinters, and one or two things heavy enough to have come down fast. The gully goes up into the dark of the rock and narrows and you cannot see the top of it from here.', 0, 0, 'mountain', 0, 78, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-foot', 'north', 'the-crag-shadow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-foot', 'south', 'the-cleft', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-goat-track', 'door', 'The Goat Track', 'A path a hand''s breadth wide traversing the slope on the level, worn into the turf by something going single file to the same place every day. It contours instead of climbing, which is how you know nothing with two legs made it. Follow it and it will take you somewhere worth going, by their reckoning.', 0, 0, 'mountain', 0, 72, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-goat-track', 'south', 'the-hearth-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-goat-track', 'east', 'the-hanging-turf', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hanging-turf', 'door', 'The Hanging Turf', 'The turf ends at a clean edge and drops, undercut, with the roots showing in a mat a foot thick and the bare slope falling away underneath. The whole skin of the hillside is peeling off here, from the bottom up. You can stand on the edge of it and feel it give very slightly.', 0, 0, 'mountain', 0, 73, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-turf', 'south', 'the-peat-hags', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-turf', 'east', 'the-wether-ledge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-turf', 'west', 'the-goat-track', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wether-ledge', 'door', 'The Wether Ledge', 'A wide grass ledge across the face, sheltered from the north, with the drop below it and the rock above it, and the grass on it cropped as short as a lawn. Everything that lives up here comes to this ledge. It is the best ground on this side of the mountain and it is not big.', 0, 0, 'mountain', 0, 74, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wether-ledge', 'north', 'the-high-fold', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wether-ledge', 'east', 'the-shelter-crag', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wether-ledge', 'west', 'the-hanging-turf', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-high-fold', 'door', 'The High Fold', 'Somebody built a wall across the neck of a natural corrie up here, once, in dry stone, to make a pen out of a shape the mountain had already made. It is the highest built thing on this hill. It is also barely a wall now, and the beasts it was for walk over it without breaking stride.', 0, 0, 'mountain', 0, 74, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-fold', 'south', 'the-wether-ledge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-fold', 'east', 'the-north-scree', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shelter-crag', 'door', 'The Shelter Crag', 'An overhang of rock leaning far enough out that the ground beneath it is dry in any weather, and everything on this mountain has stood under here at some point. Somebody has walled the windward end with stacked slabs and moved in, which is the obvious thing to do and is the reason nothing else uses this end any more. There is a smell. Some of it is his.', 1, 0, 'mountain', 1, 75, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelter-crag', 'north', 'the-north-scree', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelter-crag', 'east', 'the-raven-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelter-crag', 'west', 'the-wether-ledge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-north-scree', 'door', 'The North Scree', 'Scree on the shadowed side, wet, dark, and greasy with a film that never dries, growing nothing anywhere. It is colder here by a coat. Stones on this face are furred with a thin black crust that comes off on your hands.', 0, 0, 'mountain', 0, 75, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-scree', 'south', 'the-shelter-crag', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-scree', 'east', 'the-cairn-line', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-scree', 'west', 'the-high-fold', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-raven-stone', 'door', 'The Raven Stone', 'A blunt tower of rock standing clear of the slope, whitened down one whole side, with the ledges on it packed and trampled and the ground beneath it full of small bones and the wrappings of pellets. It is occupied. It has been occupied continuously for longer than the fortress has stood, and the tenants have never once been asked.', 0, 0, 'mountain', 0, 76, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-raven-stone', 'north', 'the-cairn-line', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-raven-stone', 'south', 'the-shattered-rib', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-raven-stone', 'east', 'the-wind-notch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-raven-stone', 'west', 'the-shelter-crag', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cairn-line', 'door', 'The Cairn Line', 'Small heaps of stone, three or four courses each, set at intervals across the shoulder and running away over the rise. They are not graves and they are not boundaries. Somebody put them here to be followed in bad weather, and the arrangement only makes sense if you are walking toward the pass, which means somebody had a reason to.', 0, 0, 'mountain', 0, 76, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cairn-line', 'south', 'the-raven-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cairn-line', 'east', 'the-bealach', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cairn-line', 'west', 'the-north-scree', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wind-notch', 'door', 'The Wind Notch', 'A gap in the shoulder that the wind uses. Even on a still day there is air moving through here hard enough to lean into, and the grass either side of the gap lies permanently flat and combed one way. Standing in it you cannot hear anything else at all.', 0, 0, 'mountain', 0, 77, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-notch', 'north', 'the-bealach', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-notch', 'west', 'the-raven-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bealach', 'door', 'The Bealach', 'The pass: the low point of the ridge, a saddle of bare ground between two rises, with the whole far side of the mountain opening beyond it and going up again out of sight. This is the way through for everything that lives here, and the ground is beaten to bare stone by the traffic of it. The cairns end here.', 0, 0, 'mountain', 0, 77, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bealach', 'south', 'the-wind-notch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bealach', 'west', 'the-cairn-line', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sphagnum-flat', 'door', 'The Sphagnum Flat', 'Moss in one continuous saturated carpet, ankle deep and holding many times its own weight in water, in colours from pale green to a deep red that reads as dried blood at a distance. Step on it and water comes up round your boot from a foot away. This is where the mountain keeps what it does not shed.', 0, 0, 'mountain', 0, 72, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sphagnum-flat', 'north', 'the-plunge-pool', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sphagnum-flat', 'east', 'the-quaking-moss', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-quaking-moss', 'door', 'The Quaking Moss', 'The moss here has grown out over standing water rather than ground, so the whole surface moves in a slow swell when you walk on it, out to a distance of several yards. There is nothing underneath but depth. People who know this ground do not cross it and there is no sign to tell you that.', 0, 0, 'mountain', 0, 73, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quaking-moss', 'east', 'the-sunk-boulders', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quaking-moss', 'west', 'the-sphagnum-flat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sunk-boulders', 'door', 'The Sunk Boulders', 'Boulders sitting in the bog with only their crowns showing, each one ringed by the moss that has crept up and over its sides. They came down the hill and stopped when they met ground that would not carry them, and they have been going down ever since, very slowly.', 0, 0, 'mountain', 0, 74, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunk-boulders', 'east', 'the-mire-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunk-boulders', 'west', 'the-quaking-moss', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-mire-foot', 'door', 'The Mire Foot', 'Where the mire runs out against rising ground, in a fringe of black water and old heather stems and hoofprints filled to the brim. Everything that crosses this flank crosses here, because it is the only edge, and the prints are layered over each other past counting.', 0, 0, 'mountain', 0, 75, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mire-foot', 'east', 'the-black-runnel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mire-foot', 'west', 'the-sunk-boulders', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-black-runnel', 'door', 'The Black Runnel', 'A narrow deep channel of peat-black water cut down through the bog, four feet deep and two feet wide with vertical sides, running fast and silent. There is no way to see the bottom and no easy way across. It comes from the force pool and it is going somewhere lower.', 0, 0, 'mountain', 0, 76, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-runnel', 'north', 'the-force-pool', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-runnel', 'east', 'the-wet-slabs', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-runnel', 'west', 'the-mire-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-slabs', 'door', 'The Slabs', 'Bare rock in great tilted sheets, swept clean of everything by the water that comes over them when the hill is full, with the joints between them opened into cracks you could put an arm down. Dry, they are the fastest walking on the mountain. They are not often dry.', 0, 0, 'mountain', 0, 77, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slabs', 'south', 'the-wet-slabs', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slabs', 'east', 'the-south-shoulder', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wet-slabs', 'door', 'The Wet Slabs', 'The same rock, lower, with a permanent film of water moving across it and a growth of black algae under the film that is as slick as anything in the world. There is no technique for this. There is only choosing whether to go on it.', 0, 0, 'mountain', 0, 77, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-slabs', 'north', 'the-slabs', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-slabs', 'west', 'the-black-runnel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-south-shoulder', 'door', 'The South Shoulder', 'The flank turns here and you come round onto ground that faces the sun, and it is a different mountain on this side: drier, browner, with heather instead of moss and the rock showing warm. You can see a great distance south. There is nothing in any of it.', 0, 0, 'mountain', 0, 78, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-shoulder', 'north', 'the-cleft', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-shoulder', 'west', 'the-slabs', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cleft', 'door', 'The Cleft', 'A fissure in the rock, a stride across at the top and narrowing out of sight, running back into the mountain further than the daylight goes. Cold air comes out of it steadily. Something has been dragging things in there — there is a scored track through the grit at the lip, going one way.', 0, 0, 'mountain', 0, 78, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cleft', 'north', 'the-gully-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cleft', 'south', 'the-south-shoulder', NULL);
